package org.usbworkbench;
import java.io.*;import java.nio.charset.*;import java.util.*;
/** Original ECMA167/UDF reader for direct type-1 partitions (common Windows ISO media).
 * Layout reference: ECMA167; Linux fs/udf/ecma_167.h. No driver code is copied.
 * Virtual/sparable/metadata partition maps and special files are explicitly rejected.
 */
final class UdfImage {
 private final OpticalImage.Source source;private final OpticalImage.Budget budget=new OpticalImage.Budget();private final DiskTools.Progress progress;
 private final Map<Integer,Part> partitions=new HashMap<>();private Part[] maps;private final Map<String,Template> cache=new HashMap<>();
 private static final class Part {final long start,count;Part(long start,long count){this.start=start;this.count=count;}}
 private static final class Ad {final int part;final long block,length;Ad(int part,long block,long length){this.part=part;this.block=block;this.length=length;}String key(){return part+":"+block;}}
 private static final class Template {final boolean dir;final long size;final List<OpticalImage.Range> ranges;Template(boolean d,long s,List<OpticalImage.Range> r){dir=d;size=s;ranges=r;}}
 private static final class Pending {final Ad ad;final String path;Pending(Ad a,String p){ad=a;path=p;}}
 private UdfImage(OpticalImage.Source source,DiskTools.Progress progress){this.source=source;this.progress=progress;}
 static int crc(byte[] b,int at,int count){int crc=0;for(int i=at;i<at+count;i++){crc^=(b[i]&255)<<8;for(int bit=0;bit<8;bit++)crc=((crc<<1)^((crc&0x8000)!=0?0x1021:0))&65535;}return crc;}
 private static int tag(byte[] b,int at,int available,int expected,long location)throws IOException{if(available<16||at<0||at+available>b.length)throw new IOException("UDF_TAG");int id=OpticalImage.u16(b,at),version=OpticalImage.u16(b,at+2),sum=0;if(expected>=0&&id!=expected||version!=2&&version!=3)throw new IOException("UDF_TAG");for(int i=0;i<16;i++)if(i!=4)sum+=b[at+i]&255;if((sum&255)!=(b[at+4]&255))throw new IOException("UDF_TAG");if(location>=0&&OpticalImage.u32(b,at+12)!=location)throw new IOException("UDF_LOCATION");int n=OpticalImage.u16(b,at+10);if(n>available-16||crc(b,at+16,n)!=OpticalImage.u16(b,at+8))throw new IOException("UDF_CRC");return id;}
 private byte[] physical(long block,int count)throws IOException{if(block<0||block>Long.MAX_VALUE/2048)throw new IOException("IMAGE_BOUNDS");budget.metadata(count);return OpticalImage.bytes(source,block*2048,count);}
 private long absolute(int part,long block,long length)throws IOException{if(maps==null||part<0||part>=maps.length||maps[part]==null)throw new IOException("UDF_PARTITION");Part p=maps[part];if(block<0||block>p.count||length<0||length>(p.count-block)*2048)throw new IOException("IMAGE_BOUNDS");return (p.start+block)*2048;}
 private byte[] partition(Ad ad,int count)throws IOException{long at=absolute(ad.part,ad.block,count);budget.metadata(count);return OpticalImage.bytes(source,at,count);}
 private static Ad longAd(byte[] b,int at)throws IOException{long raw=OpticalImage.u32(b,at);if((raw>>>30)!=0)throw new IOException("UDF_ALLOCATION");return new Ad(OpticalImage.u16(b,at+8),OpticalImage.u32(b,at+4),raw&0x3fffffffL);}
 private Ad volume(byte[] anchor)throws IOException{
  long start=OpticalImage.u32(anchor,20),length=OpticalImage.u32(anchor,16);if(length<2048||length>4*1024*1024L||length%2048!=0)throw new IOException("UDF_VOLUME");byte[] logical=null;long logicalSeq=-1;Map<Integer,Long> partSeq=new HashMap<>();
  for(long off=0;off<length;off+=2048){long block=start+off/2048;byte[] b=physical(block,2048);int id=tag(b,0,b.length,-1,block);if(id==8)break;if(id==5){int number=OpticalImage.u16(b,22);long seq=OpticalImage.u32(b,16),at=OpticalImage.u32(b,188),count=OpticalImage.u32(b,192);if(count==0||at>source.size()/2048||count>source.size()/2048-at)throw new IOException("UDF_PARTITION");if(!partSeq.containsKey(number)||seq>partSeq.get(number)){partitions.put(number,new Part(at,count));partSeq.put(number,seq);}}else if(id==6){long seq=OpticalImage.u32(b,16);if(seq>logicalSeq){logical=b;logicalSeq=seq;}}else if(id==3)throw new IOException("UDF_UNSUPPORTED");}
  if(logical==null||OpticalImage.u32(logical,212)!=2048)throw new IOException("UDF_VOLUME");long lengthMaps=OpticalImage.u32(logical,264),countMaps=OpticalImage.u32(logical,268);if(countMaps<1||countMaps>8||lengthMaps>logical.length-440)throw new IOException("UDF_PARTITION");maps=new Part[(int)countMaps];int at=440;for(int i=0;i<countMaps;i++){if(at+6>440+lengthMaps||logical[at]!=1||logical[at+1]!=6||OpticalImage.u16(logical,at+2)!=1)throw new IOException("UDF_UNSUPPORTED");maps[i]=partitions.get(OpticalImage.u16(logical,at+4));if(maps[i]==null)throw new IOException("UDF_PARTITION");at+=6;}if(at!=440+lengthMaps)throw new IOException("UDF_PARTITION");Ad fsd=longAd(logical,248);byte[] set=partition(fsd,2048);tag(set,0,set.length,256,fsd.block);return longAd(set,400);
 }
 private List<OpticalImage.Range> allocations(byte[] bytes,int at,int length,int kind,int implicit,Set<String> chain,int depth)throws IOException{
  if(depth>32||length<0||at<0||length>bytes.length-at||kind!=0&&kind!=1)throw new IOException("UDF_ALLOCATION");int step=kind==0?8:16;if(length%step!=0)throw new IOException("UDF_ALLOCATION");List<OpticalImage.Range> result=new ArrayList<>();
  for(int end=at+length;at<end;at+=step){long raw=OpticalImage.u32(bytes,at),n=raw&0x3fffffffL,lba=OpticalImage.u32(bytes,at+4);int type=(int)(raw>>>30),part=kind==0?implicit:OpticalImage.u16(bytes,at+8);if(n==0)continue;if(type==3){Ad ad=new Ad(part,lba,n);if(n>1048576||!chain.add(ad.key()))throw new IOException("IMAGE_CYCLE");int rounded=(int)((n+2047)/2048*2048);byte[] extra=partition(ad,rounded);tag(extra,0,extra.length,258,lba);long nested=OpticalImage.u32(extra,20);if(nested>extra.length-24)throw new IOException("UDF_ALLOCATION");result.addAll(allocations(extra,24,(int)nested,kind,part,chain,depth+1));if(at+step!=end)throw new IOException("UDF_ALLOCATION");}else if(type==0){result.add(new OpticalImage.Range(absolute(part,lba,n),n));}else result.add(new OpticalImage.Range(-1,n));if(result.size()>65536)throw new IOException("IMAGE_LIMIT");}
  return result;
 }
 private Template file(Ad ad)throws IOException{Template old=cache.get(ad.key());if(old!=null)return old;if(cache.size()>=OpticalImage.MAX_ENTRIES)throw new IOException("IMAGE_LIMIT");if(ad.length<176||ad.length>1048576)throw new IOException("UDF_ALLOCATION");int rounded=(int)((Math.max(2048,ad.length)+2047)/2048*2048);byte[] b=partition(ad,rounded);int id=tag(b,0,b.length,-1,ad.block);if(id!=261&&id!=266||OpticalImage.u16(b,20)!=4)throw new IOException("UDF_UNSUPPORTED");int type=b[27]&255,kind=OpticalImage.u16(b,34)&7;if(type!=4&&type!=5)throw new IOException("UDF_SPECIAL");long size=OpticalImage.u64(b,56),ea=OpticalImage.u32(b,id==261?168:208),count=OpticalImage.u32(b,id==261?172:212);int base=id==261?176:216;if(ea>b.length-base||count>b.length-base-ea)throw new IOException("UDF_ALLOCATION");int start=base+(int)ea;List<OpticalImage.Range> ranges;if(kind==3){if(size>count)throw new IOException("UDF_ALLOCATION");ranges=size==0?Collections.emptyList():Arrays.asList(new OpticalImage.Range(Arrays.copyOfRange(b,start,start+(int)size)));}else ranges=allocations(b,start,(int)count,kind,ad.part,new HashSet<>(),0);new OpticalImage.Entry("",type==4,size,ranges);Template value=new Template(type==4,size,ranges);cache.put(ad.key(),value);return value;}
 private static String filename(byte[] data,int at,int count)throws IOException{if(count<2)throw new IOException("IMAGE_NAME");int code=data[at]&255;if(code==8)return OpticalImage.decode(data,at+1,count-1,StandardCharsets.ISO_8859_1);if(code==16&&(count-1)%2==0)return OpticalImage.decode(data,at+1,count-1,StandardCharsets.UTF_16BE);throw new IOException("IMAGE_NAME");}
 private OpticalImage.Manifest tree(Ad root)throws IOException{OpticalImage.Manifest result=new OpticalImage.Manifest("UDF (direct partitions)");List<Pending> pending=new ArrayList<>();pending.add(new Pending(root,""));Set<String> visited=new HashSet<>();
  for(int index=0;index<pending.size();index++){Pending dir=pending.get(index);progress.update(index,-1);if(!visited.add(dir.ad.key()))throw new IOException("IMAGE_CYCLE");Template node=file(dir.ad);if(!node.dir)throw new IOException("UDF_DIRECTORY");if(node.size>OpticalImage.MAX_DIRECTORY)throw new IOException("IMAGE_LIMIT");budget.metadata(node.size);byte[] data=new byte[(int)node.size];OpticalImage.Entry entry=new OpticalImage.Entry(dir.path,true,node.size,node.ranges);OpticalImage.read(source,entry,0,data,0,data.length);
   for(int at=0;at<data.length;){if(data.length-at<16)throw new IOException("UDF_DIRECTORY");boolean zero=true;for(int i=0;i<16;i++)if(data[at+i]!=0)zero=false;if(zero){int next=Math.min(data.length,(at/2048+1)*2048);for(int i=at;i<next;i++)if(data[i]!=0)throw new IOException("UDF_DIRECTORY");at=next;continue;}if(data.length-at<38)throw new IOException("UDF_DIRECTORY");int chars=data[at+19]&255,impl=OpticalImage.u16(data,at+36),length=(38+impl+chars+3)&~3;if(length>data.length-at)throw new IOException("UDF_DIRECTORY");tag(data,at,length,257,-1);int flags=data[at+18]&255;if((flags&~31)!=0)throw new IOException("UDF_DIRECTORY");if((flags&12)==0){String name=filename(data,at+38+impl,chars),path=OpticalImage.safe(dir.path,name);Ad child=longAd(data,at+20);Template item=file(child);if(((flags&2)!=0)!=item.dir)throw new IOException("UDF_DIRECTORY");OpticalImage.Entry next=new OpticalImage.Entry(path,item.dir,item.size,item.ranges);result.add(next);if(item.dir)pending.add(new Pending(child,path));}at+=length;}
  }return result;
 }
 static OpticalImage.Manifest scan(OpticalImage.Source source,DiskTools.Progress progress)throws IOException{IOException last=null;long end=source.size()/2048-1;for(long where:new long[]{256,end,end-256}){if(where<0)continue;try{UdfImage reader=new UdfImage(source,progress);byte[] anchor=reader.physical(where,2048);tag(anchor,0,anchor.length,2,where);Ad root=reader.volume(anchor);return reader.tree(root);}catch(IOException e){last=e;}}throw new IOException("UDF_UNSUPPORTED_OR_DAMAGED",last);}
}
